import { useCallback, useRef } from 'react';

import { FILE_CHUNK_SIZE } from '@proton/shared/lib/drive/constants';

import { TransferState } from '../../../components/TransferManager/transfer';
import { isTransferFinished, isTransferPending, isTransferProgress } from '../../../utils/transfer';
import type { DownloadControls } from '../interface';
import type {
    Download,
    DownloadLinksProgresses,
    DownloadProgresses,
    UpdateCallback,
    UpdateFilter,
    UpdateState,
} from './interface';

export default function useDownloadControl(
    downloads: Download[],
    updateWithCallback: (idOrFilter: UpdateFilter, newState: UpdateState, callback: UpdateCallback) => void,
    removeFromQueue: (idOrFilter: UpdateFilter, callback: UpdateCallback) => void,
    clearQueue: () => void
) {
    // Controls keep references to ongoing downloads to have ability
    // to pause or cancel them.
    const controls = useRef<{ [id: string]: DownloadControls }>({});
    const progresses = useRef<DownloadProgresses>({});

    const add = (id: string, downloadControls: DownloadControls) => {
        controls.current[id] = downloadControls;
        progresses.current[id] = { progress: 0, links: {} };
    };

    const remove = (id: string) => {
        delete controls.current[id];
        delete progresses.current[id];
    };

    const getLinkProgress = (id: string, linkId: string) => {
        if (!progresses.current[id].links[linkId]) {
            progresses.current[id].links[linkId] = {
                progress: 0,
            };
        }
        return progresses.current[id].links[linkId];
    };

    const updateLinkSizes = (id: string, linkSizes: { [linkId: string]: number }) => {
        // Progress might be updated even when transfer is already finished and
        // thus progress is not here anymore. In such case it is OK to simply
        // ignore the call to not crash.
        if (progresses.current[id] === undefined) {
            return;
        }
        Object.entries(linkSizes || {}).forEach(([linkId, size]) => {
            getLinkProgress(id, linkId).total = size;
        });
    };

    const updateProgress = (id: string, linkIds: string[], increment: number) => {
        // Progress might be updated even when transfer is already finished and
        // thus progress is not here anymore. In such case it is OK to simply
        // ignore the call to not crash.
        if (progresses.current[id] === undefined) {
            return;
        }
        progresses.current[id].progress += increment;
        // Because increment can be float, some aritmetic operation can result
        // in -0.0000000001 which would be then displayed as -0 after rounding.
        if (progresses.current[id].progress < 0) {
            progresses.current[id].progress = 0;
        }

        linkIds.forEach((linkId) => (getLinkProgress(id, linkId).progress += increment));
    };

    const getProgresses = () =>
        Object.fromEntries(Object.entries(progresses.current).map(([linkId, { progress }]) => [linkId, progress]));

    const getLinksProgress = (): DownloadLinksProgresses =>
        Object.values(progresses.current).reduce((aggregatedLinks, { links }) => {
            // What if some link is downloaded more than once?
            // Probably very rare case which we can safely ignore. The worst case
            // scenario is that we show randomly progress of one download, but
            // thanks to browser caching it will not be that much off.
            return { ...aggregatedLinks, ...links };
        }, {});

    /**
     * calculateDownloadLoad returns based on progresses of ongoing downloads
     * how many data is currently being remaining to be downloaded.
     * If the size is not known yet (for example, folder which has not loaded
     * all children), it returns undefined. That should be taken as high load
     * and not start any other download for now.
     * Otherwise it returns number of remaining blocks of active transfers.
     */
    const calculateDownloadBlockLoad = (): number | undefined => {
        const progressingDownloads = downloads.filter(isTransferProgress);
        if (progressingDownloads.some(({ meta: { size } }) => size === undefined)) {
            return undefined;
        }
        return progressingDownloads.reduce((sum: number, download) => {
            const downloadedSize = progresses.current[download.id]?.progress || 0;
            return sum + Math.ceil(((download.meta.size as number) - downloadedSize) / FILE_CHUNK_SIZE);
        }, 0);
    };

    const pauseDownloads = useCallback(
        (idOrFilter: UpdateFilter) => {
            updateWithCallback(idOrFilter, TransferState.Paused, ({ id, state }) => {
                if (isTransferProgress({ state }) || isTransferPending({ state })) {
                    (controls.current[id] as DownloadControls)?.pause?.();
                }
            });
        },
        [updateWithCallback]
    );

    const resumeDownloads = useCallback(
        (idOrFilter: UpdateFilter) => {
            updateWithCallback(
                idOrFilter,
                ({ resumeState }) => {
                    return resumeState || TransferState.Progress;
                },
                ({ id }) => {
                    (controls.current[id] as DownloadControls)?.resume?.();
                }
            );
        },
        [updateWithCallback]
    );

    const cancelDownloads = useCallback(
        (idOrFilter: UpdateFilter) => {
            // Do not cancel already finished transfers.
            updateWithCallback(
                idOrFilter,
                ({ state }) => (isTransferFinished({ state }) ? state : TransferState.Canceled),
                ({ state, id }) => !isTransferFinished({ state }) && controls.current[id]?.cancel()
            );
        },
        [updateWithCallback]
    );

    const removeDownloads = useCallback(
        (idOrFilter: UpdateFilter) => {
            // We should never simply remove downloads, but cancel it first, so
            // it does not continue on background without our knowledge.
            cancelDownloads(idOrFilter);
            removeFromQueue(idOrFilter, ({ id }) => remove(id));
        },
        [removeFromQueue]
    );

    const clearDownloads = useCallback(() => {
        Object.entries(controls.current).map(([, downloadControls]) => downloadControls.cancel());
        controls.current = {};
        progresses.current = {};
        clearQueue();
    }, [clearQueue]);

    return {
        add,
        remove,
        updateLinkSizes,
        updateProgress,
        getProgresses,
        getLinksProgress,
        calculateDownloadBlockLoad,
        pauseDownloads,
        resumeDownloads,
        cancelDownloads,
        removeDownloads,
        clearDownloads,
    };
}

import type { ReadableStream } from 'web-streams-polyfill';

import type { PrivateKeyReference, PublicKeyReference, SessionKey } from '@proton/crypto';
import type { DriveFileBlock, ScanResultItem } from '@proton/shared/lib/interfaces/drive/file';
import type { SharedFileScan } from '@proton/shared/lib/interfaces/drive/sharing';

import type { DecryptedLink, SignatureIssues } from '../_links';

export type LogCallback = (message: string) => void;

export interface LinkDownload {
    isFile: boolean;
    shareId: string;
    linkId: string;

    name: string;
    mimeType: string;
    size: number;
    revisionId?: string;
    signatureAddress?: string;
    signatureIssues?: SignatureIssues;

    buffer?: Uint8Array[];
}

export type DownloadControls = {
    start: () => Promise<void>;
    pause: () => void;
    resume: () => void;
    cancel: () => void;
};

export type DownloadStreamControls = Omit<DownloadControls, 'start'> & {
    start: () => ReadableStream<Uint8Array>;
};

export type DownloadEventCallbacks = {
    // Called when the total size is known.
    onInit?: OnInitCallback;
    // Called when relative progress is changed.
    // Both up and down, e.g., when something is retried.
    onProgress?: OnProgressCallback;
    // Called when signature verification fails.
    // It can be used to ask user the issue and allow the user to abort
    // the download, or ignore the problem and continue.
    onSignatureIssue?: OnSignatureIssueCallback;
    // Called when error happened.
    // The transfer is cancelled.
    onError?: OnErrorCallback;
    // Called when network error happened.
    // The transfer is paused and it awaits for instruction to continue.
    onNetworkError?: OnErrorCallback;
    onScanIssue?: OnScanIssueCallback;
    // Called when a document is encountered.
    // The transfer is skipped.
    onContainsDocument?: OnContainsDocumentCallback;
    // Called when the whole transfer is finished.
    onFinish?: () => void;
};

type DownloadBaseCallbacks = {
    getChildren: GetChildrenCallback;
    getBlocks: GetBlocksCallback;
    getKeys: GetKeysCallback;
    scanFilesHash?: ScanFilesHashCallback;
};

export type DownloadCallbacks = DownloadEventCallbacks & DownloadBaseCallbacks;

export type OnInitCallback = (
    size: number,
    // linkSizes is map of link ID to its size.
    // Currently we collect only sizes of top level items, that
    // is excluding the whole tree of the folder item.
    linkSizes: { [linkId: string]: number }
) => void;
export type OnProgressCallback = (
    // linkIds for which the progress should be counted.
    // It should contain link itself and all the parents so the whole directory
    // tree is properly counted.
    linkIds: string[],
    bytes: number
) => void;
export type OnSignatureIssueCallback = (
    abortSignal: AbortSignal,
    link: LinkDownload,
    signatureIssues: SignatureIssues
) => Promise<void>;
type OnScanIssueCallback = (abortSignal: AbortSignal, err: any, response?: ScanResultItem) => Promise<void>;
export type OnContainsDocumentCallback = (abortSignal: AbortSignal) => Promise<void>;
type OnErrorCallback = (err: Error) => void;

export type ChildrenLinkMeta = Pick<
    DecryptedLink,
    'isFile' | 'linkId' | 'name' | 'mimeType' | 'size' | 'fileModifyTime' | 'signatureAddress' | 'signatureIssues'
>;
export type GetChildrenCallback = (
    abortSignal: AbortSignal,
    shareId: string,
    linkId: string
) => Promise<ChildrenLinkMeta[]>;
type GetBlocksCallback = (
    abortSignal: AbortSignal,
    shareId: string,
    linkId: string,
    pagination: Pagination,
    revisionId?: string,
    options?: { virusScan?: boolean }
) => Promise<{ blocks: DriveFileBlock[]; thumbnailHashes: string[]; manifestSignature: string; xAttr: string }>;
type GetKeysCallback = (abortSignal: AbortSignal, link: LinkDownload) => Promise<DecryptFileKeys>;
type ScanFilesHashCallback = (abortSignal: AbortSignal, hashes: string[]) => Promise<SharedFileScan | undefined>;

export type Pagination = { FromBlockIndex: number; PageSize: number };
export type DecryptFileKeys = {
    privateKey: PrivateKeyReference;
    sessionKeys?: SessionKey;
    addressPublicKeys?: PublicKeyReference[];
};

export type InitDownloadCallback = (
    name: string,
    list: LinkDownload[],
    eventCallbacks: DownloadEventCallbacks,
    log: LogCallback,
    options?: { virusScan?: boolean }
) => DownloadControls;

export enum TransferSignatureIssueStrategy {
    Abort = 'abort',
    Continue = 'continue',
    // Following strategies are not used yet.
}

import { useCallback, useMemo, useState } from 'react';

import { c } from 'ttag';

import { SupportedMimeTypes } from '@proton/shared/lib/drive/constants';
import generateUID from '@proton/utils/generateUID';

import type { TransferMeta } from '../../../components/TransferManager/transfer';
import { TransferState } from '../../../components/TransferManager/transfer';
import { isTransferFinished, isTransferPending } from '../../../utils/transfer';
import type { LinkDownload } from '../interface';
import type {
    Download,
    UpdateCallback,
    UpdateCallbackParams,
    UpdateData,
    UpdateFilter,
    UpdateState,
} from './interface';
import { DownloadUserError } from './interface';

type LogCallback = (id: string, message: string) => void;

export default function useDownloadQueue(log: LogCallback) {
    const [downloads, setDownloads] = useState<Download[]>([]);

    const hasDownloads = useMemo((): boolean => {
        return downloads.length > 0;
    }, [downloads]);

    const nextDownload = useMemo(() => {
        return downloads.find((download) => isTransferPending(download));
    }, [downloads]);

    const add = useCallback(async (links: LinkDownload[], options?: { virusScan?: boolean }): Promise<void> => {
        return new Promise((resolve, reject) => {
            setDownloads((downloads) => {
                if (isAlreadyDownloading(downloads, links)) {
                    reject(new DownloadUserError(generateAlreadyDownloadingError(links)));
                    return downloads;
                }
                const download = generateDownload(links, options);
                log(
                    download.id,
                    `Added item to the queue (type: ${download.meta.mimeType}, size: ${download.meta.size} bytes)`
                );
                resolve();
                return [...downloads, download];
            });
        });
    }, []);

    const update = useCallback(
        (
            idOrFilter: UpdateFilter,
            newStateOrCallback: UpdateState,
            { size, error, signatureIssueLink, signatureStatus, scanIssueError, retry }: UpdateData = {},
            callback?: UpdateCallback
        ) => {
            const filter = convertFilterToFunction(idOrFilter);
            const newStateCallback = convertNewStateToFunction(newStateOrCallback);
            const updateDownload = (download: Download): Download => {
                if (filter(download)) {
                    callback?.(download);
                    const newState = newStateCallback(download);

                    // download is considered retry if there is a manual retry
                    // This can be two way:
                    // - downloads retry restartDownloads()
                    // - download resume after a failure state resumeDownloads()
                    // It is considered retry if the download goes from an Error state to a pending/progress state
                    // download is also considered retry if we automatically retry after coming back online and having some downloads failures

                    const downloadIsARetry =
                        retry ||
                        ([TransferState.Error, TransferState.NetworkError].includes(download.state) &&
                        [TransferState.Pending, TransferState.Progress].includes(newState)
                            ? true
                            : false);
                    // If pause is set twice, prefer resumeState set already before
                    // to not be locked in paused state forever.
                    download.resumeState =
                        newState === TransferState.Paused ? download.resumeState || download.state : undefined;
                    download.state = newState;
                    if (size !== undefined) {
                        download.meta.size = size;
                    }
                    download.error = error;
                    download.signatureIssueLink = signatureIssueLink;
                    download.signatureStatus = signatureStatus;
                    download.scanIssueError = scanIssueError;
                    // download is always marked as retried after being set to true once
                    download.retries = downloadIsARetry ? (download.retries || 0) + 1 : download.retries || 0;

                    log(
                        download.id,
                        `Updated queue (state: ${newState} ${size !== undefined ? `, size: ${size}` : ''} ${error ? `, error: ${error}` : ''}, retries: ${download.retries})`
                    );
                }
                return download;
            };
            setDownloads((downloads) => [...downloads.map(updateDownload)]);
        },
        []
    );

    const updateState = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState) => {
            update(idOrFilter, newStateOrCallback);
        },
        [update]
    );

    const updateWithData = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState, data: UpdateData = {}) => {
            update(idOrFilter, newStateOrCallback, data);
        },
        [update]
    );

    const updateWithCallback = useCallback(
        (idOrFilter: UpdateFilter, newStateOrCallback: UpdateState, callback: UpdateCallback) => {
            update(idOrFilter, newStateOrCallback, {}, callback);
        },
        [update]
    );

    const remove = useCallback((idOrFilter: UpdateFilter, callback?: UpdateCallback) => {
        const filter = convertFilterToFunction(idOrFilter);
        const invertFilter: UpdateFilter = (item) => !filter(item);

        setDownloads((downloads) => {
            if (callback) {
                downloads.filter(filter).forEach((download) => callback(download));
            }
            return [...downloads.filter(invertFilter)];
        });
    }, []);

    const clear = useCallback(() => {
        setDownloads([]);
    }, []);

    return {
        downloads,
        hasDownloads,
        nextDownload,
        add,
        updateState,
        updateWithData,
        updateWithCallback,
        remove,
        clear,
    };
}

export function convertFilterToFunction(filterOrId: UpdateFilter) {
    return typeof filterOrId === 'function' ? filterOrId : ({ id }: UpdateCallbackParams) => id === filterOrId;
}

function convertNewStateToFunction(newStateOrCallback: UpdateState) {
    return typeof newStateOrCallback === 'function' ? newStateOrCallback : () => newStateOrCallback;
}

function isAlreadyDownloading(downloads: Download[], links: LinkDownload[]): boolean {
    return downloads.some((download) => {
        // User can download the same files again after previous one was
        // already finished, either canceled, failed, or downloaded.
        if (isTransferFinished(download)) {
            return false;
        }
        if (download.links.length !== links.length) {
            return false;
        }
        const ids = download.links.map((link) => link.shareId + link.linkId);
        return links.every((link) => ids.includes(link.shareId + link.linkId));
    });
}

function generateAlreadyDownloadingError(links: LinkDownload[]): string {
    if (links.length > 1) {
        return c('Error').t`File selection is already downloading`;
    }
    const { name } = links[0];
    if (!links[0].isFile) {
        return c('Error').t`Folder "${name}" is already downloading`;
    }
    return c('Error').t`File "${name}" is already downloading`;
}

function generateDownload(links: LinkDownload[], options?: { virusScan?: boolean }): Download {
    return {
        id: generateUID(),
        startDate: new Date(),
        state: TransferState.Pending,
        links,
        meta: generateDownloadMeta(links),
        options,
        retries: 0,
    };
}

function generateDownloadMeta(links: LinkDownload[]): TransferMeta {
    if (links.length === 1) {
        const link = links[0];
        if (link.isFile) {
            return {
                filename: link.name,
                mimeType: link.mimeType,
                size: link.size,
            };
        }
        return {
            filename: `${link.name}.zip`,
            mimeType: SupportedMimeTypes.zip,
        };
    }
    return {
        filename: generateMyFilesName(),
        mimeType: SupportedMimeTypes.zip,
    };
}

function generateMyFilesName(): string {
    const date = new Date().toISOString().substring(0, 19);
    // translator: Name of the download archive when selected multiple files, example: My files 2021-10-11T12:13:14.zip.
    return c('Title').t`Download ${date}`.concat('.zip');
}

import { WritableStream } from 'web-streams-polyfill';

import { isIos, isSafari } from '@proton/shared/lib/helpers/browser';
import { stripLeadingAndTrailingSlash } from '@proton/shared/lib/helpers/string';
import { PUBLIC_PATH } from '@proton/shared/lib/webpack.constants';

import type { TransferMeta } from '../../../components/TransferManager/transfer';

let workerWakeupInterval: ReturnType<typeof setInterval>;

/**
 * Safari and Edge don't support returning stream as a response.
 * Safari - has everything but fails to stream a response from SW.
 * Edge - doesn't support ReadableStream() constructor, but supports it in chromium version.
 * IOS - forces all browsers to use webkit, so same problems as safari in all browsers.
 * For them download is done in-memory using blob response.
 */
export const isUnsupported = () => {
    /* TODO: To be removed after test DRVWEB-4375 */
    if (typeof window !== 'undefined') {
        const isSWForSafariEnabled = 'isSWForSafariEnabled' in window && window.isSWForSafariEnabled;
        if (isSWForSafariEnabled) {
            return !('serviceWorker' in navigator);
        }
    }
    // Original
    return !('serviceWorker' in navigator) || isSafari() || isIos();
};

// createDownloadIframe opens download URL created in service worker to
// initialize the download in the browser. The response has headers to
// act as the download. See DownloadServiceWorker for more info.
function createDownloadIframe(src: string) {
    const iframe = document.createElement('iframe');
    iframe.hidden = true;
    iframe.src = src;
    iframe.name = 'iframe';
    document.body.appendChild(iframe);
    return iframe;
}

async function wakeUpServiceWorker(retry = true) {
    const worker = navigator.serviceWorker.controller;

    if (worker) {
        worker.postMessage({ action: 'ping' });
    } else {
        const url = [
            document.location.href.substring(0, document.location.href.indexOf('/')),
            stripLeadingAndTrailingSlash(PUBLIC_PATH),
            'sw/ping',
        ]
            .filter(Boolean)
            .join('/');
        const res = await fetch(url);
        const body = await res.text();
        if (!res.ok || body !== 'pong') {
            if (!retry) {
                throw new Error('Download worker is dead');
            }
            console.warn('Download worker is dead, retrying registration');
            await initDownloadSW();
            await wakeUpServiceWorker(false);
        }
    }
    return worker as ServiceWorker;
}

function serviceWorkerKeepAlive() {
    clearInterval(workerWakeupInterval);
    workerWakeupInterval = setInterval(() => {
        wakeUpServiceWorker().catch(() => clearInterval(workerWakeupInterval));
    }, 10000);
}

export async function initDownloadSW() {
    if (isUnsupported()) {
        throw new Error('Saving file via download is unsupported by this browser');
    }

    await navigator.serviceWorker
        .register(
            /* webpackChunkName: "downloadSW" */
            new URL('./downloadSW', import.meta.url),
            {
                scope: `/${stripLeadingAndTrailingSlash(PUBLIC_PATH)}`,
            }
        )
        .then((registration) => {
            // We do not cache manifest for local server or this can cause HMR to infinite reload
            if (!window.location.host.includes('proton.local')) {
                /*
                Upon sending cache_assets action we fetch all assets using the Service Worker
                Diagram can be seen here using the mermaid diagram file applications/drive/src/app/store/_downloads/fileSaver/mermaid-cache-assets-diagram.json to be uploaded on https://mermaid.live/
            */
                if (registration.active?.state === 'activated') {
                    registration.active.postMessage({ action: 'cache_assets' });
                } else if (registration.installing) {
                    registration.installing.addEventListener('statechange', () => {
                        if (registration.active?.state === 'activated') {
                            registration.active.postMessage({ action: 'cache_assets' });
                        }
                    });
                }
            }
        });

    serviceWorkerKeepAlive();
}

/**
 * Opens download stream into service worker. Use abort signal when pipeTo can't close the download stream.
 */
export async function openDownloadStream(
    meta: TransferMeta,
    { onCancel, abortSignal }: { onCancel: () => void; abortSignal?: AbortSignal }
) {
    const channel = new MessageChannel();
    const stream = new WritableStream({
        write(block: Uint8Array) {
            channel.port1.postMessage({ action: 'download_chunk', payload: block });
        },
        close() {
            channel.port1.postMessage({ action: 'end' });
        },
        abort(reason) {
            channel.port1.postMessage({ action: 'abort', reason: String(reason) });
        },
    });

    if (abortSignal) {
        abortSignal.addEventListener('abort', () => {
            channel.port1.postMessage({ action: 'abort', reason: 'Download stream aborted' });
        });
    }

    const worker = await wakeUpServiceWorker();

    // Channel to stream file contents through
    channel.port1.onmessage = ({ data }) => {
        if (data?.action === 'download_canceled') {
            onCancel();
        } else if (data?.action === 'download_started') {
            createDownloadIframe(data.payload);
        }
    };
    worker.postMessage({ action: 'start_download', payload: meta }, [channel.port2]);

    return stream;
}

import { SupportedMimeTypes } from '@proton/shared/lib/drive/constants';
import type { Api } from '@proton/shared/lib/interfaces';

import { TransferCancel } from '../../../components/TransferManager/transfer';
import { HEARTBEAT_MAX_REFRESH_TIME, HEARTBEAT_WAIT_TIME } from '../constants';
import fileSaver from '../fileSaver/fileSaver';
import type {
    DownloadCallbacks,
    DownloadControls,
    DownloadStreamControls,
    LinkDownload,
    LogCallback,
} from '../interface';
import initDownloadLinkFile from './downloadLinkFile';
import initDownloadLinkFolder from './downloadLinkFolder';
import initDownloadLinks from './downloadLinks';

/**
 * SIZE_WAIT_TIME limits how long wait before initializing download by browser.
 * The download is already progressing during that time, it just waits for info
 * to properly decide whether to use streaming or buffering solution.
 * 5 seconds is probably reasonable number to have plenty of time to prefer
 * buffer solution (more probably faster one) in most cases, but not waiting
 * too long to not buffer too much of data in memory (to fit in memory), and
 * also in case of using streaming solution to show the download more quickly
 * to user (to have nicer UX).
// See SizeTimeoutPromise for more information.
 */
const SIZE_WAIT_TIME = 5000; // ms

/**
 * initDownload prepares controls for downloading either file, folder or set
 * of files, based on the provided links.
 * One file link: the file is downloaded directly.
 * One folder link: archive is generated, all childs are in the root.
 * Many links: archive is generated, all files are in the root.
 */
export default function initDownload(
    name: string,
    links: LinkDownload[],
    callbacks: DownloadCallbacks,
    log: LogCallback,
    api: Api,
    options?: { virusScan?: boolean }
): DownloadControls {
    let gotErr: any;
    const heartbeat = new HeartbeatTimeout(log);

    const sizePromise = new SizeTimeoutPromise(SIZE_WAIT_TIME);
    const controls = getControls(
        links,
        {
            onInit: (size, linkSizes) => {
                callbacks.onInit?.(size, linkSizes);
                sizePromise.set(size);
                heartbeat.refreshTimeout();
            },
            onProgress: (...args) => {
                callbacks.onProgress?.(...args);
                heartbeat.refreshTimeout();
            },
            onSignatureIssue: async (...args) => {
                heartbeat.pauseTimeout();
                return callbacks.onSignatureIssue?.(...args);
            },
            onError: (err) => {
                callbacks.onError?.(err);
                gotErr = err;
                heartbeat.pauseTimeout();
            },
            onNetworkError: (err) => {
                callbacks.onNetworkError?.(err);
                heartbeat.pauseTimeout();
            },
            onScanIssue: async (...args) => {
                heartbeat.pauseTimeout();
                return callbacks.onScanIssue?.(...args);
            },
            onContainsDocument: async (...args) => {
                heartbeat.pauseTimeout();
                return callbacks.onContainsDocument?.(...args);
            },
            onFinish: (...args) => {
                callbacks.onFinish?.(...args);
                heartbeat.pauseTimeout();
            },
            getChildren: (...args) => {
                heartbeat.refreshTimeout();
                return callbacks.getChildren(...args);
            },
            getBlocks: (...args) => {
                heartbeat.refreshTimeout();
                return callbacks.getBlocks(...args);
            },
            getKeys: (...args) => {
                heartbeat.refreshTimeout();
                return callbacks.getKeys(...args);
            },
            scanFilesHash: async (...args) => {
                heartbeat.refreshTimeout();
                return callbacks.scanFilesHash?.(...args);
            },
        },
        log,
        api,
        options
    );

    heartbeat.onTimeout = () => {
        // TODO: At this moment we send this to Sentry only. Metric must be used here.
        gotErr = new Error('Transfer got stuck');
        controls.cancel();
    };

    return {
        start: async () => {
            const stream = controls.start();
            const size = await sizePromise.get().catch(() => undefined);
            await fileSaver
                .saveAsFile(
                    stream,
                    {
                        filename: name,
                        mimeType: links.length === 1 ? links[0].mimeType : SupportedMimeTypes.zip,
                        size,
                    },
                    log
                )
                .catch((err) => {
                    callbacks.onError?.(err);
                    controls.cancel();
                    throw err;
                });
            if (gotErr) {
                throw gotErr;
            }
            callbacks.onFinish?.();
            heartbeat.pauseTimeout();
        },
        pause: () => {
            controls.pause();
            heartbeat.pauseTimeout();
        },
        resume: () => {
            controls.resume();
            heartbeat.refreshTimeout();
        },
        cancel: () => {
            gotErr = new TransferCancel({ message: `Transfer canceled` });
            controls.cancel();
            heartbeat.pauseTimeout();
        },
    };
}

export function initDownloadStream(links: LinkDownload[], callbacks: DownloadCallbacks, api: Api) {
    // Stream is used in direct preview. There we do not support logs just yet.
    const noLog = () => {};
    return getControls(links, callbacks, noLog, api);
}

function getControls(
    links: LinkDownload[],
    callbacks: DownloadCallbacks,
    log: LogCallback,
    api: Api,
    options?: { virusScan?: boolean }
): DownloadStreamControls {
    if (links.length === 1) {
        const link = links[0];
        if (link.isFile) {
            return initDownloadLinkFile(link, callbacks, log, options);
        }
        return initDownloadLinkFolder(link, callbacks, log, api, options);
    }
    return initDownloadLinks(links, callbacks, log, api, options);
}

/**
 * Loading deep folder structure can take awhile, but we don't want to wait
 * till the whole structure is loaded before we start actually downloading
 * the files. The issue is, FileSaver needs to know the size to properly
 * decide whether to use service worker (for huge files) or simpler buffer
 * solution (for small files). We can say if the size is not known in some
 * reasonable time, then the structure is huge and archive probably big.
 * If the size is not provided, service worker solution is used by default.
 * There is still fallback if service worker is not working, so this is good
 * enough precision.
 */
class SizeTimeoutPromise {
    promise: Promise<number>;

    resolve?: (value: number) => void;

    constructor(timeout: number) {
        let reject: (err?: any) => void;
        this.promise = new Promise((_resolve, _reject) => {
            this.resolve = _resolve;
            reject = _reject;
        });
        setTimeout(() => reject(), timeout);
